func main() {
	// Read the contents of /proc/version
	data, err := ioutil.ReadFile("/proc/version")
	if err != nil {
		fmt.Println("Error reading /proc/version:", err)
		return
	}

	// Convert the data to a string
	versionInfo := string(data)

	// Split the string to find the kernel release
	// The format is usually: "Linux version <kernel_release> ..."
	parts := strings.Fields(versionInfo)
	if len(parts) < 3 {
		fmt.Println("Unexpected format in /proc/version")
		return
	}

	// The kernel release is the third word
	kernelRelease := parts[2]

	// Print the kernel release
	fmt.Println("Kernel Release:", kernelRelease)
}
